package com.example.inventory.ui;
import com.example.inventory.models.*;import com.example.inventory.services.InventoryService;import javafx.beans.property.SimpleStringProperty;import javafx.collections.FXCollections;import javafx.geometry.Insets;import javafx.scene.Node;import javafx.scene.control.*;import javafx.scene.layout.*;import java.util.*;
public class InventoryController{private final InventoryService s;private final TableView<Item> items=new TableView<>();private final TableView<Vendor> vendors=new TableView<>();private final Label status=new Label("Ready");public InventoryController(InventoryService s){this.s=s;config();}public Node createView(){BorderPane r=new BorderPane();r.setPadding(new Insets(15));Label t=new Label("Inventory Management System");t.setStyle("-fx-font-size:24px;-fx-font-weight:bold;");r.setTop(new VBox(8,t,status));TabPane p=new TabPane(new Tab("Items",itemsView()),new Tab("Vendors",vendorsView()));p.getTabs().forEach(x->x.setClosable(false));r.setCenter(p);refresh();return r;}private Node itemsView(){Button a=new Button("Add Item"),e=new Button("Edit"),d=new Button("Delete"),in=new Button("Stock In"),out=new Button("Stock Out"),r=new Button("Refresh");a.setOnAction(x->addItem());e.setOnAction(x->editItem());d.setOnAction(x->delItem());in.setOnAction(x->stock("IN"));out.setOnAction(x->stock("OUT"));r.setOnAction(x->refresh());HBox b=new HBox(8,a,e,d,in,out,r);b.setPadding(new Insets(10));return new VBox(b,items);}private Node vendorsView(){Button a=new Button("Add Vendor"),e=new Button("Edit"),d=new Button("Delete"),r=new Button("Refresh");a.setOnAction(x->addVendor());e.setOnAction(x->editVendor());d.setOnAction(x->delVendor());r.setOnAction(x->refresh());HBox b=new HBox(8,a,e,d,r);b.setPadding(new Insets(10));return new VBox(b,vendors);}private void config(){TableColumn<Item,String>i=new TableColumn<>("ID"),n=new TableColumn<>("Name"),q=new TableColumn<>("Quantity"),v=new TableColumn<>("Vendor ID");i.setCellValueFactory(x->new SimpleStringProperty(""+x.getValue().getId()));n.setCellValueFactory(x->new SimpleStringProperty(x.getValue().getName()));q.setCellValueFactory(x->new SimpleStringProperty(""+x.getValue().getQuantity()));v.setCellValueFactory(x->new SimpleStringProperty(""+x.getValue().getVendorId()));items.getColumns().setAll(i,n,q,v);items.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);TableColumn<Vendor,String>vi=new TableColumn<>("ID"),vn=new TableColumn<>("Name"),vc=new TableColumn<>("Contact");vi.setCellValueFactory(x->new SimpleStringProperty(""+x.getValue().getId()));vn.setCellValueFactory(x->new SimpleStringProperty(x.getValue().getName()));vc.setCellValueFactory(x->new SimpleStringProperty(x.getValue().getContactInfo()));vendors.getColumns().setAll(vi,vn,vc);vendors.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);}private boolean dialog(String title,List<TextField>f){Dialog<ButtonType>d=new Dialog<>();d.setTitle(title);VBox b=new VBox(8);for(TextField x:f){x.setPrefWidth(320);b.getChildren().add(x);}d.getDialogPane().setContent(b);d.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);return d.showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK;}private int num(String x){return x==null||x.isBlank()?0:Integer.parseInt(x);}private void addItem(){List<TextField>f=Arrays.asList(new TextField(),new TextField(),new TextField());if(dialog("Add Item",f))try{s.addItem(new Item(0,f.get(0).getText(),Integer.parseInt(f.get(1).getText()),num(f.get(2).getText())));refresh();}catch(Exception e){err(e.getMessage());}}private void editItem(){Item x=items.getSelectionModel().getSelectedItem();if(x==null){err("Select an item");return;}List<TextField>f=Arrays.asList(new TextField(x.getName()),new TextField(""+x.getQuantity()),new TextField(x.getVendorId()>0?""+x.getVendorId():""));if(dialog("Edit Item",f))try{x.setName(f.get(0).getText());x.setQuantity(Integer.parseInt(f.get(1).getText()));x.setVendorId(num(f.get(2).getText()));s.updateItem(x);refresh();}catch(Exception e){err(e.getMessage());}}private void delItem(){Item x=items.getSelectionModel().getSelectedItem();if(x==null){err("Select an item");return;}try{s.removeItem(x.getId());refresh();}catch(Exception e){err(e.getMessage());}}private void stock(String type){Item x=items.getSelectionModel().getSelectedItem();if(x==null){err("Select an item");return;}TextInputDialog d=new TextInputDialog();d.setTitle(type.equals("IN")?"Stock In":"Stock Out");d.setHeaderText(x.getName());d.setContentText("Quantity");d.showAndWait().ifPresent(v->{try{s.adjustStock(x.getId(),Integer.parseInt(v),type);refresh();}catch(Exception e){err(e.getMessage());}});}private void addVendor(){List<TextField>f=Arrays.asList(new TextField(),new TextField());if(dialog("Add Vendor",f))try{s.addVendor(new Vendor(0,f.get(0).getText(),f.get(1).getText()));refresh();}catch(Exception e){err(e.getMessage());}}private void editVendor(){Vendor x=vendors.getSelectionModel().getSelectedItem();if(x==null){err("Select a vendor");return;}List<TextField>f=Arrays.asList(new TextField(x.getName()),new TextField(x.getContactInfo()));if(dialog("Edit Vendor",f))try{x.setName(f.get(0).getText());x.setContactInfo(f.get(1).getText());s.updateVendor(x);refresh();}catch(Exception e){err(e.getMessage());}}private void delVendor(){Vendor x=vendors.getSelectionModel().getSelectedItem();if(x==null){err("Select a vendor");return;}try{s.removeVendor(x.getId());refresh();}catch(Exception e){err(e.getMessage());}}private void refresh(){try{items.setItems(FXCollections.observableArrayList(s.getAllItems()));vendors.setItems(FXCollections.observableArrayList(s.getAllVendors()));status.setText("Items: "+items.getItems().size()+" | Vendors: "+vendors.getItems().size()+" | Low stock (<=5): "+s.getLowStockItems(5).size());}catch(Exception e){err(e.getMessage());}}private void err(String m){status.setText("Error: "+m);new Alert(Alert.AlertType.ERROR,m).showAndWait();}}